    'description' => 'This is a test attribute',
    'sort_order' => (int) 1,
    'created' => object(Cake\I18n\Time) {
        'time' => '2016-08-12T15:08:06+02:00',
        'timezone' => 'Europe/Berlin',
        'fixedNowTime' => false
    },
    'modified' => object(Cake\I18n\Time) {
        'time' => '2016-08-12T15:08:06+02:00',
        'timezone' => 'Europe/Berlin',
        'fixedNowTime' => false
    },
    'attribute_values' => [
        (int) 0 => object(App\Model\Entity\AttributeValue) {
            'id' => (int) 1,
            'name' => 'Test 1',
            'created' => object(Cake\I18n\Time) {
                'time' => '2016-08-08T10:38:18+02:00',
                'timezone' => 'Europe/Berlin',
                'fixedNowTime' => false
            },
            'modified' => object(Cake\I18n\Time) {
